'use client';
import { useEffect, useState } from 'react';
import { motion, useAnimation } from 'framer-motion';

export default function ConstructionProgress({ lang }) {
  const [progress, setProgress] = useState(65); // Example progress
  const controls = useAnimation();

  useEffect(() => {
    controls.start({
      width: `${progress}%`,
      transition: { duration: 1.5, ease: "easeOut" }
    });
  }, [progress, controls]);

  return (
    <div className="bg-amber-50 py-16 px-4">
      <div className="max-w-4xl mx-auto">
        <h2 className="text-3xl font-bold text-center mb-4 text-amber-800">
          {lang === 'en' ? 'Mandapam Construction Progress' : 'மண்டபம் கட்டுமான முன்னேற்றம்'}
        </h2>
        <p className="text-center mb-8 text-gray-700">
          {lang === 'en' 
            ? 'We are building a new mandapam for temple ceremonies' 
            : 'நாங்கள் கோவில் சடங்குகளுக்கு ஒரு புதிய மண்டபத்தை கட்டி வருகிறோம்'}
        </p>
        
        <div className="mb-4 flex justify-between">
          <span className="text-amber-800 font-medium">
            {lang === 'en' ? 'Current Progress' : 'தற்போதைய முன்னேற்றம்'}
          </span>
          <span className="text-amber-800 font-bold">{progress}%</span>
        </div>
        
        <div className="w-full bg-gray-200 rounded-full h-4 mb-8">
          <motion.div
            initial={{ width: 0 }}
            animate={controls}
            className="bg-amber-600 h-4 rounded-full"
          />
        </div>
        
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {[
            {
              en: 'Foundation Completed',
              ta: 'அடித்தளம் முடிந்தது',
              date: '15 Jan 2024'
            },
            {
              en: 'Pillars Construction',
              ta: 'தூண்கள் கட்டுமானம்',
              date: 'In Progress'
            },
            {
              en: 'Expected Completion',
              ta: 'எதிர்பார்க்கப்படும் நிறைவு',
              date: 'Dec 2024'
            }
          ].map((item, index) => (
            <motion.div
              key={index}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: index * 0.2 }}
              className="bg-white p-6 rounded-lg shadow-md border border-amber-100"
            >
              <h3 className="text-lg font-bold text-amber-800 mb-2">
                {item[lang]}
              </h3>
              <p className="text-gray-600">{item.date}</p>
            </motion.div>
          ))}
        </div>
        
        <div className="mt-12 text-center">
          <h3 className="text-xl font-bold text-amber-800 mb-4">
            {lang === 'en' ? 'Support Our Construction' : 'எங்கள் கட்டுமானத்தை ஆதரிக்கவும்'}
          </h3>
          <button className="bg-amber-600 hover:bg-amber-700 text-white px-8 py-3 rounded-full text-lg font-medium transition-all duration-300 transform hover:scale-105 shadow-lg">
            {lang === 'en' ? 'Donate Now' : 'இப்போது நன்கொடை அளிக்கவும்'}
          </button>
        </div>
      </div>
    </div>
  );
}